import{_ as t,J as s,b as n,e as r,a8 as i,f as o,L as d}from"./chunks/framework.C-MVLAPI.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Paths","entity":"TCanvas32","kind":"Class","declaration":"TCanvas32 = class(TCustomCanvas)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomPath","TFlattenedPath","TCustomCanvas","TCanvas32"],"summary":"High-level 2D vector canvas rendering engine bound to a TBitmap32 target, managing brushes, text rendering, and polygon rasterization.","date":1788520319000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Paths/TCanvas32/index.md","filePath":"api/GR32_Paths/Classes/TCanvas32/index.md","lastUpdated":1788520319000,"timestamp":1788520319000,"datetime":"2026-09-04T11:11:59.000Z","contributors":[]}'),l={name:"api/GR32_Paths/TCanvas32/index.md"};function p(c,e,h,T,u,m){const a=s("ApiMembers");return n(),r("div",null,[e[0]||(e[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCanvas32</code> is the primary 2D vector drawing canvas in Graphics32. It binds path construction directives inherited from <a href="/api/GR32_Paths/TCustomPath/">TCustomPath</a> and <a href="/api/GR32_Paths/TFlattenedPath/">TFlattenedPath</a> directly to a target <a href="/api/GR32/TBitmap32/">TBitmap32</a> surface.</p><p>Key capabilities of <code>TCanvas32</code> include:</p><ul><li><strong>Bitmap Drawing Target</strong>: Operates directly on an assigned <a href="/api/GR32_Paths/TCanvas32/Bitmap">Bitmap</a> instance (<a href="/api/GR32/TBitmap32/">TBitmap32</a>).</li><li><strong>Brush Collection Pipeline</strong>: Manages a collection of vector stroke and fill brushes in <a href="/api/GR32_Paths/TCanvas32/Brushes">Brushes</a> (<a href="/api/GR32_Brushes/TBrushCollection/">TBrushCollection</a>), applying solid colors, strokes, dashes, or custom pattern fillers during path rendering.</li><li><strong>Configurable Polygon Renderer</strong>: Uses an anti-aliased software polygon renderer (<a href="/api/GR32_Paths/TCanvas32/Renderer">Renderer</a>, <a href="/api/GR32_Paths/TCanvas32/RendererClassName">RendererClassName</a>) such as <code>TPolygonRenderer32VPR</code> or <code>TPolygonRenderer32LCD</code> to rasterize paths.</li><li><strong>Vector Text Outline Rendering</strong>: Converts TrueType/OpenType font outlines into vector path geometry via <a href="/api/GR32_Paths/TCanvas32/RenderText">RenderText</a> and measures text layout bounds via <a href="/api/GR32_Paths/TCanvas32/MeasureText">MeasureText</a>.</li></ul>',4)),o("p",null,[d(a,{type:"members"})])])}const C=t(l,[["render",p]]);export{g as __pageData,C as default};
